 private void updateSound(){sound.setText(audio.enabled()?"Sonido: encendido":"Sonido: apagado");sound.setToolTipText(audio.available()?"Silenciar ambiente y botones":"El audio no está disponible; la instalación funciona igualmente");}
 private void showStep(int selected){step=selected;String[] titles={"ANTES DE SALIR…","ENCUENTRA TU REFUGIO","PREPARA TU EQUIPO","ÚLTIMA COMPROBACIÓN",finished?"TRANSMISIÓN COMPLETADA":"TRANSMISIÓN EN CURSO"};String[] subtitles={"Un asistente para preparar tu mundo, paso a paso.","Búsqueda automática o selección manual de Minecraft.","Añade JAR, ZIP o carpetas. El instalador los acomoda.","Versiones, archivos y respaldos antes de aplicar los cambios.",finished?"Tu instalación está lista para abrirse desde el launcher.":"Espera mientras se respalda e instala el pack."};pageTitle.setText(titles[step]);pageSubtitle.setText(subtitles[step]);steps.show(pages,Integer.toString(step));for(int i=0;i<5;i++)trail[i].setForeground(i==step?RED:i<step?TEXT:MUTED);back.setEnabled(!busy&&step>0&&!finished);cancel.setEnabled(!busy);next.setVisible(step!=3);install.setVisible(step==3);next.setText(step==4?"Finalizar":step==2?"Revisar":"Continuar");next.setEnabled(!busy&&(step<4||finished));install.setEnabled(!busy&&plan!=null&&plan.allowed());}
 private void advance(){try{if(step==4){close();return;}if(step==1){if(!Files.isDirectory(instance()))throw new IOException("Elige una carpeta de Minecraft existente.");refreshWorlds();}if(step==2){if(pack.files().isEmpty())throw new IOException("Añade tus componentes antes de continuar.");showStep(3);review();return;}showStep(step+1);}catch(Exception e){error(e);}}
 private void close(){if(busy){JOptionPane.showMessageDialog(frame,"Espera a que termine la operación antes de cerrar.","Instalación en curso",JOptionPane.INFORMATION_MESSAGE);return;}audio.close();if(frame!=null)frame.dispose();}
 private void invalidatePlan(){plan=null;install.setEnabled(false);finished=false;}
 private void updatePack(){packName.setText(pack.files().isEmpty()?"PACK MODULAR · AÑADE TUS ARCHIVOS":pack.mode().equals("full")?"PACK COMPLETO":"PACK MODULAR");loader.setText("Minecraft "+pack.minecraft()+"  /  NeoForge "+pack.neoForge());Map<String,Long> countsBy=new LinkedHashMap<>();for(Engine.Entry f:pack.files())countsBy.merge(f.path().split("/")[0],1L,Long::sum);componentModel.setRowCount(0);for(Engine.Entry file:pack.files())componentModel.addRow(new Object[]{file.path().split("/")[0],file.path()});counts.setText("Mods "+countsBy.getOrDefault("mods",0L)+"   ·   Resourcepacks "+countsBy.getOrDefault("resourcepacks",0L)+"   ·   Shaders "+countsBy.getOrDefault("shaderpacks",0L)+"   ·   Datapacks "+countsBy.getOrDefault("datapacks",0L)+"   ·   Config "+countsBy.getOrDefault("config",0L));}
 private List<Path> candidates(){Set<Path> found=new LinkedHashSet<>();String user=System.getProperty("user.home"),appData=System.getenv().getOrDefault("APPDATA",user);for(Path dir:List.of(Path.of(user,"curseforge","minecraft","Instances"),Path.of(user,"Documents","CurseForge","Minecraft","Instances"),Path.of(user,"Documents","curseforge","minecraft","Instances"))){if(Files.isDirectory(dir))try(var paths=Files.list(dir)){for(Path p:paths.filter(Files::isDirectory).toList())if(Files.isRegularFile(p.resolve("minecraftinstance.json")))found.add(p);}catch(IOException ignored){}}for(Path p:List.of(Path.of(appData,".minecraft"),Path.of(user,".minecraft")))if(Files.isDirectory(p)&&Files.isDirectory(p.resolve("versions")))found.add(p);for(Path config:List.of(Path.of(user,".tlauncher","tlauncher-2.0.properties"),Path.of(appData,".tlauncher","tlauncher-2.0.properties"))){if(Files.isRegularFile(config))try(var in=Files.newInputStream(config)){Properties props=new Properties();props.load(in);String dir=props.getProperty("minecraft.gamedir");if(dir!=null&&Files.isDirectory(Path.of(dir)))found.add(Path.of(dir));}catch(IOException ignored){}}return List.copyOf(found);}
 private void discover(){List<Path> all=candidates(),preferred=all.stream().filter(p->p.getFileName().toString().toLowerCase(Locale.ROOT).contains("zomb")).toList();if(preferred.size()==1){path.setText(preferred.get(0).toString());refreshWorlds();}else if(all.size()==1){path.setText(all.get(0).toString());refreshWorlds();}}
 private void detectInstance(){List<Path> all=candidates();if(all.isEmpty()){JOptionPane.showMessageDialog(frame,"No se encontró Minecraft en las carpetas habituales.\nUsa Elegir carpeta y selecciona la instancia de CurseForge o la carpeta .minecraft de TLauncher.","Selección manual",JOptionPane.INFORMATION_MESSAGE);return;}Object choice=JOptionPane.showInputDialog(frame,"Elige dónde instalar el pack:","Minecraft detectado",JOptionPane.QUESTION_MESSAGE,null,all.toArray(),all.get(0));if(choice!=null){path.setText(choice.toString());refreshWorlds();}}
 private Path instance()throws IOException {if(path.getText().isBlank())throw new IOException("Elige la carpeta de la instancia, por ejemplo ZOMBIES POLDO.");return Path.of(path.getText()).toAbsolutePath().normalize();}
 private List<String> selectedWorlds(){Object w=world.getSelectedItem();if(w==null||w.toString().equals("Sin mundo seleccionado"))return List.of();return List.of(w.toString());}
 private void refreshWorlds(){world.removeAllItems();world.addItem("Sin mundo seleccionado");try{for(String w:Engine.worlds(instance()))world.addItem(w);}catch(IOException ignored){}}
 private JFileChooser chooser(boolean folder){JFileChooser c=new JFileChooser();c.setDialogTitle(folder?"Elige la carpeta de tu instancia":"Selecciona un archivo ZIP");c.setFileSelectionMode(folder?JFileChooser.DIRECTORIES_ONLY:JFileChooser.FILES_ONLY);return c;}
 private void chooseInstance(){JFileChooser c=chooser(true);if(c.showOpenDialog(frame)==JFileChooser.APPROVE_OPTION){path.setText(c.getSelectedFile().toString());refreshWorlds();}}
 private void setBusy(boolean value){busy=value;for(Component c:List.of(review,importPack,readComponents,savePack,emptyPack,detect,export,restore,browse,path,world,keys,fixImport,findDependency,copyReport,saveReport,openLogs))c.setEnabled(!value);install.setEnabled(!value&&plan!=null&&plan.allowed());progress.setIndeterminate(value);showStep(step);tools.setEnabled(!value);}
 private <T>void work(String title,Callable<T> task,java.util.function.Consumer<T> done){if(busy)return;diagnostics.event(title);setBusy(true);state.setText(title);new SwingWorker<T,String>(){protected T doInBackground()throws Exception{return task.call();}protected void done(){setBusy(false);try{done.accept(get());}catch(Exception e){Throwable cause=e.getCause()==null?e:e.getCause();state.setText("No se pudo completar. Consulta el detalle.");if(step==4){invalidatePlan();finishTitle.setText("TRANSMISIÓN INTERRUMPIDA");finishDetail.setText("Revisa el error y vuelve a la comprobación.");}showError(cause);}}}.execute();}
 private void report(String message){diagnostics.event(message);SwingUtilities.invokeLater(()->state.setText(message));}
 private void review(){invalidatePlan();try{if(pack.files().isEmpty())throw new IOException("Añade tus componentes antes de revisar la instalación.");Path dest=instance();List<String> worlds=selectedWorlds();Engine.Pack chosen=pack;work("Comprobando versiones y archivos…",()->Engine.review(chosen,dest,worlds,this::report),p->{plan=p;diagnostics.review(p);refreshChecks();install.setEnabled(p.allowed());state.setText(p.allowed()?p.copies().size()+" archivos para instalar; originales guardados en respaldo.":"Resuelve los problemas mostrados. Puedes añadir el JAR faltante y volver a revisar.");});}catch(Exception e){error(e);}}
 private void install(){if(plan==null)return;finished=false;showStep(4);finishTitle.setText("PREPARANDO EL REFUGIO");finishDetail.setText("Respaldo y copia de archivos en curso.");Engine.Plan p=plan;boolean apply=keys.isSelected();work("Preparando respaldo…",()->Engine.install(p,apply,this::report),backup->{state.setText("Instalación terminada. Respaldo: "+backup.getFileName());plan=null;finished=true;finishTitle.setText("TU REFUGIO ESTÁ LISTO");finishDetail.setText("Pack instalado. Tus archivos originales están respaldados.");progress.setIndeterminate(false);progress.setValue(100);pageTitle.setText("TRANSMISIÓN COMPLETADA");showStep(4);});}
 private void importPack(){JFileChooser c=chooser(false);c.setDialogTitle("Añade JAR, ZIP o carpetas");c.setFileSelectionMode(JFileChooser.FILES_AND_DIRECTORIES);c.setMultiSelectionEnabled(true);if(c.showOpenDialog(frame)!=JFileChooser.APPROVE_OPTION)return;List<Path> inputs=Arrays.stream(c.getSelectedFiles()).map(File::toPath).toList();if(inputs.isEmpty())inputs=List.of(c.getSelectedFile().toPath());addInputs(inputs);}
 private void addInputs(List<Path> inputs){Engine.Pack current=pack;work("Identificando y acomodando componentes…",()->Lego.assemble(current,inputs,Files.createDirectories(home.resolve("imports")),this::report),p->{pack=p;invalidatePlan();model.setRowCount(0);updatePack();state.setText("Componentes añadidos. Revisa antes de instalar o guarda el pack ZIP.");if(step==3)review();});}
 private void savePack(){JFileChooser c=chooser(false);c.setSelectedFile(new File("Zombies-Poldo-modular.zip"));if(c.showSaveDialog(frame)!=JFileChooser.APPROVE_OPTION)return;Path target=c.getSelectedFile().toPath();if(Files.exists(target)&&JOptionPane.showConfirmDialog(frame,"¿Reemplazar este ZIP?","Guardar pack",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;Engine.Pack current=pack;work("Guardando pack modular…",()->{Lego.save(current,target);return target;},p->state.setText("Pack guardado: "+p.getFileName()));}
 private void exportPack(){try{Path source=instance();JFileChooser c=chooser(false);c.setSelectedFile(new File("Zombies-Poldo-pack-completo.zip"));if(c.showSaveDialog(frame)!=JFileChooser.APPROVE_OPTION)return;Path target=c.getSelectedFile().toPath();if(Files.exists(target)&&JOptionPane.showConfirmDialog(frame,"¿Reemplazar este ZIP?","Exportar pack",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;String w=selectedWorlds().stream().findFirst().orElse(null);work("Empaquetando tu instancia…",()->{Engine.exportInstance(source,target,w,pack.minecraft(),pack.neoForge(),this::report);return target;},p->state.setText("Pack completo exportado: "+p.getFileName()));}catch(Exception e){error(e);}}
 private void restore(){try{Path source=instance();if(JOptionPane.showConfirmDialog(frame,"Se restaurarán los archivos de la última instalación.\nSi los modificaste después, se detendrá para conservar tus cambios.","Restaurar respaldo",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;work("Restaurando los originales…",()->{Engine.restoreLatest(source);return source;},p->{invalidatePlan();state.setText("Respaldo restaurado.");});}catch(Exception e){error(e);}}
 private void error(Exception e){showError(e);}
 private void showError(Throwable e){diagnostics.error("Error del instalador",e);String message=Objects.toString(e.getMessage(),e.getClass().getSimpleName());state.setText("Error guardado en logs. Usa Copiar diagnóstico o Guardar informe.");if(GraphicsEnvironment.isHeadless())return;JTextArea text=new JTextArea(message+"\n\nLog: "+diagnostics.log());text.setEditable(false);text.setLineWrap(true);text.setWrapStyleWord(true);JScrollPane pane=new JScrollPane(text);pane.setPreferredSize(new Dimension(650,160));JOptionPane.showMessageDialog(frame,pane,"Error guardado · detalle",JOptionPane.ERROR_MESSAGE);}
 private void refreshChecks(){if(plan==null)return;model.setRowCount(0);long bad=plan.checks().stream().filter(c->!c.good()).count();reviewSummary.setText(bad+" bloqueos · "+plan.checks().stream().filter(c->c.group().equals("Aviso de dependencias")).count()+" avisos de dependencias · "+plan.copies().size()+" archivos para copiar");plan.checks().stream().sorted(Comparator.comparing(Engine.Check::good)).filter(c->!onlyProblems.isSelected()||!c.good()).forEach(c->model.addRow(new Object[]{c.good()?"OK":"!",c.group(),c.title(),c.detail()}));detail.setText(bad==0?"Sin problemas. Puedes instalar; los originales se guardarán en un respaldo.":"Selecciona un problema. Verás qué archivo lo necesita y cómo corregirlo.");if(model.getRowCount()>0&&reviewTable!=null)reviewTable.setRowSelectionInterval(0,0);}
 private void saveReport(){JFileChooser c=chooser(false);c.setSelectedFile(new File("diagnostico-zombies-poldo.txt"));if(c.showSaveDialog(frame)==JFileChooser.APPROVE_OPTION)try{diagnostics.save(c.getSelectedFile().toPath());state.setText("Informe guardado: "+c.getSelectedFile());}catch(IOException e){error(e);}}
 private void findDependency(){if(reviewTable==null||reviewTable.getSelectedRow()<0){state.setText("Selecciona primero una dependencia faltante.");return;}int r=reviewTable.convertRowIndexToModel(reviewTable.getSelectedRow());if(!model.getValueAt(r,1).equals("Dependencias")){state.setText("Este problema no es una dependencia. Consulta el detalle de la fila.");return;}String id=model.getValueAt(r,2).toString().split(" ")[0];try{Desktop.getDesktop().browse(URI.create("https://www.curseforge.com/minecraft/search?class=mc-mods&search="+java.net.URLEncoder.encode(id,java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){error(e);}}

 public static void main(String[] args)throws Exception {Path base=Path.of(App.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toAbsolutePath();if(Files.isRegularFile(base))base=base.getParent();if(args.length>0&&args[0].equals("--preview")){System.setProperty("java.awt.headless","true");App app=new App(Path.of(args[1]));SwingUtilities.invokeAndWait(()->{JPanel ui=app.build();app.path.setText("C:\\Users\\Bacon\\curseforge\\minecraft\\Instances\\ZOMBIES POLDO");app.model.addRow(new Object[]{"✓","NeoForge","21.1.255","Versión correcta"});app.model.addRow(new Object[]{"✓","Mods","Dungeons ISO v17","Actualizar · se guardará el original"});app.model.addRow(new Object[]{"✓","Mods","Zomboid Integration 1.7.3","Correcto · no se vuelve a copiar"});app.model.addRow(new Object[]{"✓","Teclas","Linterna X · GUI 3","Aplicar perfil del pack"});app.showStep(args.length>3?Integer.parseInt(args[3]):0);ui.setSize(1180,760);layout(ui);BufferedImage image=new BufferedImage(1180,760,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();ui.paint(g);g.dispose();try{ImageIO.write(image,"png",Path.of(args[2]).toFile());}catch(IOException e){throw new RuntimeException(e);}});return;}
  Path home=base;Thread.setDefaultUncaughtExceptionHandler((thread,error)->{try{new Diagnostics(home).error("Error no controlado en "+thread.getName(),error);}catch(IOException logError){error.printStackTrace();}});SwingUtilities.invokeLater(()->{try{UIManager.setLookAndFeel(UIManager.getCrossPlatformLookAndFeelClassName());UIManager.put("Button.disabledText",MUTED);UIManager.put("ComboBox.background",CARD);UIManager.put("ComboBox.foreground",TEXT);App app=new App(home);JFrame f=new JFrame("Zombies Poldo · Instalador");app.frame=f;f.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);f.addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){app.close();}});f.setContentPane(app.build());f.setMinimumSize(new Dimension(1040,700));f.setSize(1180,790);f.setLocationRelativeTo(null);f.setVisible(true);}catch(Exception e){try{Diagnostics d=new Diagnostics(home);d.error("No se pudo iniciar",e);JOptionPane.showMessageDialog(null,Objects.toString(e.getMessage(),e.toString())+"\n\nDetalle guardado en: "+d.folder(),"No se pudo iniciar",JOptionPane.ERROR_MESSAGE);}catch(IOException logging){e.printStackTrace();JOptionPane.showMessageDialog(null,e.toString(),"No se pudo iniciar",JOptionPane.ERROR_MESSAGE);}}});
 }
